import 'dart:async';
import 'dart:math' as math;

import 'package:audioplayers/audioplayers.dart';
import 'package:flutter/material.dart';

/// The launch animation: the book opens, the path climbs out of it, and the
/// goal dot lights up with a shine — the app icon assembling itself.
///
/// Shapes are the icon's own (design/icon/masar-icon.svg, a 1024 canvas), so
/// the last frame is the icon exactly. The preview this was tuned against is
/// ~/Desktop/Masar-Splash/preview.html; the sound is generated by
/// make_shine.py there.
class MasarSplashAnimation extends StatefulWidget {
  const MasarSplashAnimation({super.key, this.onFinished, this.playSound = true});

  /// Called once the last frame is on screen.
  final VoidCallback? onFinished;

  /// Off in widget tests, where there is no audio plugin.
  final bool playSound;

  static const duration = Duration(milliseconds: 3200);

  @override
  State<MasarSplashAnimation> createState() => _MasarSplashAnimationState();
}

class _MasarSplashAnimationState extends State<MasarSplashAnimation>
    with SingleTickerProviderStateMixin {
  late final AnimationController _c =
      AnimationController(vsync: this, duration: MasarSplashAnimation.duration);
  AudioPlayer? _player;
  Timer? _soundTimer;
  bool _started = false;

  @override
  void didChangeDependencies() {
    super.didChangeDependencies();
    if (_started) return;
    _started = true;
    // Reduced motion: show the finished icon, no shine.
    if (MediaQuery.of(context).disableAnimations) {
      _c.value = 1;
      WidgetsBinding.instance.addPostFrameCallback((_) => widget.onFinished?.call());
      return;
    }
    _c.forward().whenComplete(() {
      if (mounted) widget.onFinished?.call();
    });
    if (widget.playSound) {
      // The bell sits 0.33 s into the file; start it so the bell lands on the
      // frame where the dot lights up (1.88 s).
      _soundTimer = Timer(const Duration(milliseconds: 1550), _shine);
    }
  }

  Future<void> _shine() async {
    try {
      final player = _player = AudioPlayer();
      // Respect the silent switch and don't stop the user's music.
      await player.setAudioContext(AudioContextConfig(
        focus: AudioContextConfigFocus.mixWithOthers,
        respectSilence: true,
      ).build());
      await player.play(AssetSource('sound/shine.m4a'), volume: 0.8);
    } catch (_) {
      // A missing sound must never block the launch.
    }
  }

  @override
  void dispose() {
    _soundTimer?.cancel();
    _player?.dispose();
    _c.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final text = Theme.of(context).textTheme;
    return AnimatedBuilder(
      animation: _c,
      builder: (context, _) {
        final t = _c.value;
        final word = _seg(t, 2300, 2900, Curves.easeOut);
        return Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            LayoutBuilder(builder: (context, box) {
              final side = math.min(box.maxWidth * 0.72, 320.0);
              return SizedBox.square(
                dimension: side,
                child: CustomPaint(painter: _SplashPainter(t)),
              );
            }),
            const SizedBox(height: 8),
            Opacity(
              opacity: word,
              child: Transform.translate(
                offset: Offset(0, 10 * (1 - word)),
                child: Column(children: [
                  Text('مسار',
                      style: text.displaySmall?.copyWith(
                          color: Colors.white, fontWeight: FontWeight.w900, height: 1.2)),
                  Text('MASAR',
                      style: text.labelMedium?.copyWith(
                          color: _Splash.glow.withValues(alpha: 0.85), letterSpacing: 5)),
                ]),
              ),
            ),
          ],
        );
      },
    );
  }
}

/// The timeline in milliseconds of the 3.2 s run, as in the preview.
double _seg(double t, int fromMs, int toMs, [Curve curve = Curves.linear]) {
  final total = MasarSplashAnimation.duration.inMilliseconds;
  final v = ((t * total - fromMs) / (toMs - fromMs)).clamp(0.0, 1.0);
  return curve.transform(v);
}

abstract final class _Splash {
  static const navy = Color(0xFF1B3866);
  static const pageR = Color(0xFFE4EEF9);
  static const lines = Color(0xFF9FB6D6);
  static const glow = Color(0xFF5FF5E4);
  static const dot = Offset(625, 255);
}

class _SplashPainter extends CustomPainter {
  _SplashPainter(this.t);
  final double t;

  static final _route = Path()
    ..moveTo(512, 610)
    ..cubicTo(512, 500, 390, 480, 420, 400)
    ..cubicTo(445, 335, 560, 330, 610, 270);
  static final _pageL = Path()
    ..moveTo(512, 625)
    ..cubicTo(430, 572, 320, 560, 205, 595)
    ..lineTo(205, 790)
    ..cubicTo(320, 755, 430, 765, 512, 820)
    ..close();
  static final _pageR = Path()
    ..moveTo(512, 625)
    ..cubicTo(594, 572, 704, 560, 819, 595)
    ..lineTo(819, 790)
    ..cubicTo(704, 755, 594, 765, 512, 820)
    ..close();
  static final _pageLines = Path()
    ..moveTo(255, 640)
    ..cubicTo(330, 618, 410, 620, 470, 650)
    ..moveTo(255, 690)
    ..cubicTo(330, 668, 410, 670, 470, 700);

  static const _overshootPop = Cubic(.2, 1.6, .4, 1);
  static const _draw = Cubic(.55, .05, .35, 1);

  @override
  void paint(Canvas canvas, Size size) {
    canvas.save();
    canvas.scale(size.width / 1024);

    // The glow and its expanding ring, behind everything.
    final g = _seg(t, 1880, 2980);
    if (g > 0) {
      final rise = (g / .25).clamp(0.0, 1.0);
      final scale = g < .25 ? .2 + 1.4 * rise : 1.6 - .6 * ((g - .25) / .75);
      canvas.drawCircle(
        _Splash.dot,
        130 * scale,
        Paint()
          ..shader = RadialGradient(colors: [
            _Splash.glow.withValues(alpha: .65 * rise),
            _Splash.glow.withValues(alpha: 0),
          ]).createShader(Rect.fromCircle(center: _Splash.dot, radius: 130 * scale)),
      );
    }
    final b = _seg(t, 1900, 2800, Curves.easeOut);
    if (b > 0 && b < 1) {
      canvas.drawCircle(
        _Splash.dot,
        70 * (.3 + 2.9 * b),
        Paint()
          ..style = PaintingStyle.stroke
          ..strokeWidth = 6
          ..color = _Splash.glow.withValues(alpha: .9 * (1 - b)),
      );
    }

    // The path climbing out of the book.
    final d = _seg(t, 1000, 1900, _draw);
    if (d > 0) {
      final metric = _route.computeMetrics().first;
      canvas.drawPath(
        metric.extractPath(0, metric.length * d),
        Paint()
          ..style = PaintingStyle.stroke
          ..strokeWidth = 58
          ..strokeCap = StrokeCap.round
          ..color = Colors.white,
      );
    }

    // The book opening from its spine.
    final o = _seg(t, 250, 1000, Curves.easeOutBack);
    if (o > 0) {
      for (final (path, color, skew) in [
        (_pageL, Colors.white, .14),
        (_pageR, _Splash.pageR, -.14),
      ]) {
        canvas.save();
        canvas.translate(512, 720);
        canvas.scale(o, 1);
        canvas.skew(0, skew * (1 - o.clamp(0.0, 1.0)));
        canvas.translate(-512, -720);
        canvas.drawPath(path, Paint()..color = color);
        canvas.restore();
      }
      canvas.drawLine(
        const Offset(512, 625),
        const Offset(512, 820),
        Paint()
          ..color = _Splash.navy
          ..strokeWidth = 10,
      );
    }
    final l = _seg(t, 850, 1200);
    if (l > 0) {
      canvas.drawPath(
        _pageLines,
        Paint()
          ..style = PaintingStyle.stroke
          ..strokeWidth = 12
          ..strokeCap = StrokeCap.round
          ..color = _Splash.lines.withValues(alpha: l),
      );
    }

    // The goal dot pops in, and sparks fly off it.
    final p = _seg(t, 1880, 2380, _overshootPop);
    if (p > 0) {
      canvas.save();
      canvas.translate(_Splash.dot.dx, _Splash.dot.dy);
      canvas.scale(p);
      canvas.drawCircle(Offset.zero, 62, Paint()..color = _Splash.glow);
      canvas.drawCircle(const Offset(-18, -18), 17,
          Paint()..color = Colors.white.withValues(alpha: .75));
      canvas.restore();
    }
    final s = _seg(t, 1920, 2720, Curves.easeOut);
    if (s > 0 && s < 1) {
      final fade = s < .2 ? s / .2 : 1 - (s - .2) / .8;
      for (var i = 0; i < 10; i++) {
        final a = i / 10 * 2 * math.pi + (i * 37 % 10) / 25;
        final dist = (120 + (i * 53 % 90)) * s;
        canvas.drawCircle(
          _Splash.dot + Offset(math.cos(a) * dist, math.sin(a) * dist),
          (7 + (i * 29 % 6)) * (.4 + .6 * s),
          Paint()..color = (i % 3 == 0 ? Colors.white : _Splash.glow).withValues(alpha: fade),
        );
      }
    }
    canvas.restore();
  }

  @override
  bool shouldRepaint(_SplashPainter old) => old.t != t;
}
